content.content:
// Shared fade schedule for multi-sensory learning scaffolding (consonant
// class color, tone contour icons, …), keyed to the app's existing SRS
// stage names. Scaffolding should train recognition early, then get out of
// the way as a word is mastered — otherwise the visual aids never come off
// and a learner never transfers to reading unmarked real Thai text.
export type ScaffoldLevel = "full" | "fading" | "none";

const LEVEL_BY_STAGE: Record<string, ScaffoldLevel> = {
	Apprentice: "full",
	Guru: "full",
	Master: "full",
	Enlightened: "fading",
	Burned: "none",
};

/** No stage (e.g. a word not yet reviewed) gets full scaffolding — a new word deserves full support. */
export function scaffoldLevel(stageName?: string | null): ScaffoldLevel {
	if (!stageName) return "full";
	return LEVEL_BY_STAGE[stageName] ?? "full";
}
---WordCard.tsx---
import { assignRoom } from "../../../domain/vocabulary/data/rooms";
import {
	composeVocabMnemonic,
	mnemonicStateFor,
	roomLabel,
} from "../../../domain/vocabulary/services/VocabMnemonic";
import type { VocabEntry } from "../../../domain/vocabulary/types";
import {
	classBadgeStyle,
	classColorForLevel,
} from "../../utils/consonantClassColor";
import { scaffoldLevel } from "../../utils/srsFade";
import { ToneContourIcon } from "../atoms/ToneContourIcon";
import { MnemonicBlock } from "../molecules/MnemonicBlock";

function PlayAudioButton({ audioUrl }: { audioUrl: string }) {
	return (
		<button
			type="button"
			onClick={() => new Audio(audioUrl).play()}
			className="ml-3 inline-flex items-center justify-center w-10 h-10 rounded-full transition-colors align-middle"
			style={{
				background: "var(--color-surface-2)",
				color: "var(--color-text-muted)",
			}}
			aria-label="Play pronunciation"
		>
			🔊
		</button>
	);
}

function InlinePlayButton({ audioUrl }: { audioUrl: string }) {
	return (
		<button
			type="button"
			onClick={() => new Audio(audioUrl).play()}
			className="inline-flex items-center justify-center w-7 h-7 rounded-full transition-colors shrink-0"
			style={{
				background: "var(--color-surface-2)",
				color: "var(--color-text-muted)",
			}}
			aria-label="Play audio"
		>
			<span className="text-xs">🔊</span>
		</button>
	);
}

function syllableTypeStyle(type: string): React.CSSProperties {
	if (type === "live") {
		return {
			background:
				"color-mix(in srgb, var(--color-master) 12%, var(--color-surface))",
			color: "var(--color-master)",
		};
	}
	return {
		background:
			"color-mix(in srgb, var(--color-danger) 12%, var(--color-surface))",
		color: "var(--color-danger)",
	};
}

export function WordCard({
	word,
	stageName,
}: {
	word: VocabEntry;
	/** This word's SRS stage name (e.g. "Burned"), if known — fades the color/tone scaffolding as mastery grows. Omit for a not-yet-reviewed word, which gets full scaffolding. */
	stageName?: string | null;
}) {
	const hasDecomposition = word.syllables.some(
		(s) => s.initialConsonant || s.vowel || s.finalConsonant,
	);
	const visibleSamples = word.samples.filter((s) => s.thai);
	const level = scaffoldLevel(stageName);
	// The staged, room-grammar mnemonic where this entry has one; the corpus's
	// own prose otherwise. Matched on rank as well as spelling — two corpus
	// entries can share a spelling and only one of them is the word staged.
	const staged = mnemonicStateFor(word);
	const mnemonicText =
		staged.state === "has-mnemonic"
			? composeVocabMnemonic(staged.mnemonic)
			: word.mnemonic;
	// This is a browse surface: the meaning, the romanization and the class are
	// all already on screen, so the room confirms rather than cues. The rule
	// that keeps it off a *review* prompt lives in `Flashcard`.
	const roomAssignment = assignRoom(word.word_class);

	return (
		<div className="space-y-4">
			{/* 1. Hero — Image + Word + Audio */}
			<div className="text-center">
				{word.image_file && (
					<div className="flex justify-center mb-4">
						<img
							src={word.image_file}
							alt={word.english}
							className="rounded-xl object-contain max-h-64 w-full"
							style={{ background: "var(--color-surface-2)" }}
						/>
					</div>
				)}
				<span className="thai text-[72px]" style={{ lineHeight: 1.15 }}>
					{word.thai}
				</span>
				{word.thai_audio_file && (
					<PlayAudioButton audioUrl={word.thai_audio_file} />
				)}
				<p className="text-2xl font-semibold mt-2">{word.english}</p>
				<p className="text-sm" style={{ color: "var(--color-text-muted)" }}>
					{word.romanization}
				</p>
				{word.word_class && (
					<span
						className="inline-block mt-1 px-2 py-0.5 rounded text-xs font-semibold"
						style={{
							background: "var(--color-surface-2)",
							color: "var(--color-text-muted)",
						}}
					>
						{word.word_class}
					</span>
				)}
				{roomAssignment.state === "assigned" && (
					<span
						className="inline-block mt-1 ml-1 px-2 py-0.5 rounded text-xs font-semibold"
						style={{
							background: "var(--color-surface-2)",
							color: "var(--color-text-muted)",
						}}
					>
						Room: {roomLabel(roomAssignment.room)}
					</span>
				)}
				{word.description && (
					<p
						className="text-sm mt-3 text-center"
						style={{ color: "var(--color-text-muted)" }}
					>
						{word.description}
					</p>
				)}
			</div>

			{/* 2. Mnemonic */}
			{mnemonicText && <MnemonicBlock text={mnemonicText} label="Memory tip" />}

			{/* 3. Syllable Breakdown (enriched) */}
			{word.syllables.length > 0 && (
				<div
					className="rounded-xl p-4"
					style={{ background: "var(--color-surface-2)" }}
				>
					<p
						className="text-xs font-semibold mb-3"
						style={{ color: "var(--color-text-muted)" }}
					>
						Syllable Breakdown
					</p>
					<div className="space-y-3">
						{word.syllables.map((syl, i) => (
							<div
								key={`${syl.text}-${i}`}
								className="pb-3 last:pb-0 last:border-0"
								style={{ borderBottom: "1px solid var(--color-border)" }}
							>
								<div className="flex items-center justify-between mb-1">
									<span className="thai text-lg">{syl.text}</span>
									<div className="flex items-center gap-1.5 text-xs">
										{syl.consonantClass && (
											<span
												className="px-2 py-0.5 rounded font-semibold capitalize"
												style={classBadgeStyle(syl.consonantClass)}
											>
												{syl.consonantClass}
											</span>
										)}
										{syl.tone && (
											<span
												className="flex items-center gap-1 px-2 py-0.5 rounded font-semibold"
												style={{
													background:
														"color-mix(in srgb, var(--color-primary) 12%, var(--color-surface))",
													color: "var(--color-primary)",
												}}
											>
												{level !== "none" && (
													<ToneContourIcon
														tone={syl.tone}
														style={{
															opacity: level === "fading" ? 0.5 : 1,
														}}
													/>
												)}
												{syl.tone}
											</span>
										)}
										{syl.syllableType && (
											<span
												className="px-2 py-0.5 rounded font-semibold"
												style={syllableTypeStyle(syl.syllableType)}
											>
												{syl.syllableType}
											</span>
										)}
									</div>
								</div>
								{hasDecomposition && (
									<div
										className="flex items-center gap-2 text-xs mt-1"
										style={{ color: "var(--color-text-muted)" }}
									>
										{syl.initialConsonant && (
											<span>
												<span className="opacity-60">initial </span>
												<span
													className="thai text-sm font-semibold"
													style={{
														color:
															classColorForLevel(syl.consonantClass, level) ??
															"var(--color-text)",
													}}
												>
													{syl.initialConsonant}
												</span>
											</span>
										)}
										{syl.vowel && (
											<>
												<span className="opacity-40">→</span>
												<span>
													<span className="opacity-60">vowel </span>
													<span
														className="thai text-sm font-semibold"
														style={{ color: "var(--color-text)" }}
													>
														{syl.vowel}
													</span>
												</span>
											</>
										)}
										{syl.finalConsonant && (
											<>
												<span className="opacity-40">→</span>
												<span>
													<span className="opacity-60">final </span>
													<span
														className="thai text-sm font-semibold"
														style={{ color: "var(--color-text)" }}
													>
														{syl.finalConsonant}
													</span>
												</span>
											</>
										)}
										{syl.toneMark && (
											<>
												<span className="opacity-40">→</span>
												<span>
													<span className="opacity-60">mark </span>
													<span
														className="text-sm font-semibold"
														style={{ color: "var(--color-text)" }}
													>
														{syl.toneMark}
													</span>
												</span>
											</>
										)}
									</div>
								)}
							</div>
						))}
					</div>
				</div>
			)}

			{/* 4. Example Sentences */}
			{visibleSamples.length > 0 && (
				<div
					className="rounded-xl p-4"
					style={{ background: "var(--color-surface-2)" }}
				>
					<p
						className="text-xs font-semibold mb-3"
						style={{ color: "var(--color-text-muted)" }}
					>
						Examples
					</p>
					<div className="space-y-3">
						{visibleSamples.map((sample) => (
							<div
								key={sample.thai}
								className="pb-3 last:pb-0 last:border-0"
								style={{ borderBottom: "1px solid var(--color-border)" }}
							>
								<div className="flex items-start gap-2">
									<p className="thai text-base leading-relaxed flex-1">
										{sample.thai}
									</p>
									{sample.thai_audio_file && (
										<InlinePlayButton audioUrl={sample.thai_audio_file} />
									)}
								</div>
								{sample.romanization && (
									<p
										className="text-xs mt-1 italic"
										style={{ color: "var(--color-text-muted)" }}
									>
										{sample.romanization}
									</p>
								)}
								{sample.english && (
									<p
										className="text-sm mt-1"
										style={{ color: "var(--color-text-muted)" }}
									>
										{sample.english}
									</p>
								)}
							</div>
						))}
					</div>
				</div>
			)}
		</div>
	);
}

