				<span className="thai text-[72px]" style={{ lineHeight: 1.15 }}>
					{word.thai}
				</span>
				{word.thai_audio_file && (
					<PlayAudioButton audioUrl={word.thai_audio_file} />
				)}
				<p className="text-2xl font-semibold mt-2">{word.english}</p>
				<p className="text-sm" style={{ color: "var(--color-text-muted)" }}>
					{word.romanization}
				</p>
				{word.word_class && (
					<span
						className="inline-block mt-1 px-2 py-0.5 rounded text-xs font-semibold"
						style={{
							background: "var(--color-surface-2)",
							color: "var(--color-text-muted)",
						}}
					>
						{word.word_class}
					</span>
				)}
				{roomAssignment.state === "assigned" && (
					<span
						className="inline-block mt-1 ml-1 px-2 py-0.5 rounded text-xs font-semibold"
						style={{
							background: "var(--color-surface-2)",
							color: "var(--color-text-muted)",
						}}
					>
						Room: {roomLabel(roomAssignment.room)}
					</span>
				)}
				{word.description && (
					<p
						className="text-sm mt-3 text-center"
						style={{ color: "var(--color-text-muted)" }}
					>
						{word.description}
					</p>
				)}
			</div>

			{/* 2. Mnemonic */}
			{mnemonicText && <MnemonicBlock text={mnemonicText} label="Memory tip" />}

			{/* 3. Syllable Breakdown (enriched) */}
			{word.syllables.length > 0 && (
				<div
					className="rounded-xl p-4"
					style={{ background: "var(--color-surface-2)" }}
				>
					<p
						className="text-xs font-semibold mb-3"
						style={{ color: "var(--color-text-muted)" }}
					>
						Syllable Breakdown
					</p>
					<div className="space-y-3">
						{word.syllables.map((syl, i) => (
							<div
								key={`${syl.text}-${i}`}
								className="pb-3 last:pb-0 last:border-0"
								style={{ borderBottom: "1px solid var(--color-border)" }}
							>
								<div className="flex items-center justify-between mb-1">
									<span className="thai text-lg">{syl.text}</span>
									<div className="flex items-center gap-1.5 text-xs">
										{syl.consonantClass && (
											<span
												className="px-2 py-0.5 rounded font-semibold capitalize"
												style={classBadgeStyle(syl.consonantClass)}
											>
												{syl.consonantClass}
											</span>
										)}
										{syl.tone && (
											<span
												className="flex items-center gap-1 px-2 py-0.5 rounded font-semibold"
												style={{
													background:
														"color-mix(in srgb, var(--color-primary) 12%, var(--color-surface))",
													color: "var(--color-primary)",
												}}
											>
												{level !== "none" && (
													<ToneContourIcon
														tone={syl.tone}
														style={{
															opacity: level === "fading" ? 0.5 : 1,
														}}
													/>
												)}
												{syl.tone}
											</span>
										)}
										{syl.syllableType && (
											<span
												className="px-2 py-0.5 rounded font-semibold"
												style={syllableTypeStyle(syl.syllableType)}
											>
												{syl.syllableType}
											</span>
										)}
									</div>
								</div>
								{hasDecomposition && (
									<div
										className="flex items-center gap-2 text-xs mt-1"
										style={{ color: "var(--color-text-muted)" }}
									>
										{syl.initialConsonant && (
											<span>
												<span className="opacity-60">initial </span>
												<span
													className="thai text-sm font-semibold"
													style={{
														color:
															classColorForLevel(syl.consonantClass, level) ??
															"var(--color-text)",
													}}
												>
													{syl.initialConsonant}
												</span>
											</span>
										)}
										{syl.vowel && (
											<>
												<span className="opacity-40">→</span>
												<span>
													<span className="opacity-60">vowel </span>
													<span
														className="thai text-sm font-semibold"
														style={{ color: "var(--color-text)" }}
													>
														{syl.vowel}
													</span>
												</span>
											</>
										)}
										{syl.finalConsonant && (
											<>
												<span className="opacity-40">→</span>
												<span>
													<span className="opacity-60">final </span>
													<span
														className="thai text-sm font-semibold"
														style={{ color: "var(--color-text)" }}
													>
														{syl.finalConsonant}
													</span>
												</span>
											</>
										)}
										{syl.toneMark && (
											<>
												<span className="opacity-40">→</span>
												<span>
													<span className="opacity-60">mark </span>
													<span
														className="text-sm font-semibold"
														style={{ color: "var(--color-text)" }}
													>
														{syl.toneMark}
													</span>
												</span>
											</>
										)}
									</div>
								)}
							</div>
						))}
					</div>
				</div>
			)}

			{/* 4. Example Sentences */}
			{visibleSamples.length > 0 && (
				<div
					className="rounded-xl p-4"
					style={{ background: "var(--color-surface-2)" }}
				>
					<p
						className="text-xs font-semibold mb-3"
						style={{ color: "var(--color-text-muted)" }}
					>
						Examples
					</p>
					<div className="space-y-3">
						{visibleSamples.map((sample) => (
							<div
								key={sample.thai}
								className="pb-3 last:pb-0 last:border-0"
								style={{ borderBottom: "1px solid var(--color-border)" }}
							>
								<div className="flex items-start gap-2">
									<p className="thai text-base leading-relaxed flex-1">
										{sample.thai}
									</p>
									{sample.thai_audio_file && (
										<InlinePlayButton audioUrl={sample.thai_audio_file} />
									)}
								</div>
								{sample.romanization && (
									<p
										className="text-xs mt-1 italic"
										style={{ color: "var(--color-text-muted)" }}
									>
										{sample.romanization}
									</p>
								)}
								{sample.english && (
									<p
										className="text-sm mt-1"
										style={{ color: "var(--color-text-muted)" }}
									>
										{sample.english}
									</p>
								)}
							</div>
						))}
					</div>
				</div>
			)}
		</div>
	);
}

