import { withDottedCircles } from "../../utils/thaiText";
import { PlayAudioButton } from "./PlayAudioButton";

interface Props {
	character: string;
	/** Tailwind size class, e.g. "text-8xl" or "text-[10rem]" */
	className?: string;
