		<p
			className="text-center text-sm mt-2"
			style={{ color: "var(--color-text-muted)" }}
		>
			Room: {roomLabel(room)}
			{via === "hint" && <span className="ml-1 opacity-60">(hint)</span>}
		</p>
	);
}

