		"symbolCharacter" in card
			? ((card as Record<string, unknown>).symbolCharacter as string)
			: "";
	const symbolClass =
		"consonantClass" in card
			? ((card as Record<string, unknown>).consonantClass as string | undefined)
			: undefined;
