					style={{ color: "var(--color-text-muted)" }}
				>
					{card.question}
				</p>
			</div>

			{!revealed ? (
				<>
					{room && roomExposure?.visible === false && (
						<button
							type="button"
							onClick={() => setRoomHintRequested(true)}
							className="w-full py-2 rounded-xl text-sm"
							style={{
								background: "transparent",
								color: "var(--color-text-muted)",
							}}
						>
							Stuck? Show the room
						</button>
					)}
