						<p
							className={`text-2xl font-bold${!hasTopAudio && card.audioUrl ? " thai" : ""}`}
							style={{ color: "var(--color-primary)" }}
						>
							{card.correctAnswer}
						</p>
						{!hasTopAudio && card.audioUrl && (
							<button
								type="button"
								onClick={() => {
									if (card.audioUrl) {
